return $input.all().map((item) => {
  const data = item.json;

  const subject =
    data.subject ||
    data.Subject ||
    data.headers?.subject ||
    data.headers?.Subject ||
    "";

  const from =
    data.from?.text ||
    data.from ||
    data.From ||
    data.headers?.from ||
    data.headers?.From ||
    "";

  let emailBody =
    data.text ||
    data.html ||
    data.email_body ||
    data.snippet ||
    "";

  emailBody = String(emailBody)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<\/div>/gi, "\n")
    .replace(/<\/tr>/gi, "\n")
    .replace(/<\/li>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s*\n\s*\n+/g, "\n\n")
    .trim();

  // Replace long URLs with short placeholders to save Gemini tokens
  const urlMap = {};
  let urlIndex = 1;

  const emailBodyWithUrlKeys = emailBody.replace(/https?:\/\/[^\s]+/g, (url) => {
    const key = `URL_${urlIndex}`;
    urlMap[key] = url;
    urlIndex++;
    return key;
  });

  return {
    json: {
      gmail_message_id: data.id,
      email_subject: subject,
      email_from: from,
      email_date: data.date || data.internalDate || "",
      email_body: emailBody,
      url_map: urlMap,

      // Shorter, faster Gemini input
      email_body_for_ai: emailBodyWithUrlKeys.slice(0, 10000),
    },
  };
});

function formatAirtableDate(value) {
  if (!value) return "";

  // If Gmail gives ISO date: 2026-06-14T11:00:06.000Z
  if (typeof value === "string" && value.includes("T")) {
    return value.split("T")[0];
  }

  // If Gmail gives internalDate as milliseconds string
  if (!isNaN(value)) {
    return new Date(Number(value)).toISOString().split("T")[0];
  }

  return value;
}

return $input.all().flatMap((item) => {
  const data = item.json;

  // Get original email details from the Clean Email Text node
  const sourceEmail = $("Clean Email Text").first().json;

  const emailDate = formatAirtableDate(sourceEmail.email_date || "");
  const urlMap = sourceEmail.url_map || {};

  // Gemini output is inside content.parts[0].text
  let rawText = data.content?.parts?.[0]?.text || "";

  // Safety cleanup in case Gemini adds markdown/code fences
  rawText = rawText
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(rawText);
  } catch (error) {
    throw new Error(
      "Failed to parse Gemini JSON: " +
        error.message +
        "\nRaw text: " +
        rawText
    );
  }

  const jobs = parsed.jobs || [];

  return jobs.map((job) => ({
    json: {
      job_title: job.job_title || "",
      company: job.company || "",
      platform: job.platform || "Other",

      // Restores real URL if Gemini returned URL_1 / URL_2 / etc.
      job_url: urlMap[job.job_url] || job.job_url || "",

      job_type: job.job_type || "Not specified",
      email_preview: job.email_preview || "",
      email_match_score: Number(job.email_match_score || 0),
      match_level: job.match_level || "Low Match",
      status: job.status || "Email Preview Only",
      email_date: emailDate,
      ai_reason: job.ai_reason || "",

      missing_skills: Array.isArray(job.missing_skills)
        ? job.missing_skills.join(", ")
        : job.missing_skills || "",

      matching_skills: Array.isArray(job.matching_skills)
        ? job.matching_skills.join(", ")
        : job.matching_skills || "",

      red_flags: Array.isArray(job.red_flags)
        ? job.red_flags.join(", ")
        : job.red_flags || "",
    },
  }));
});
